/// <summary>
/// PricingAttribute of table <c>CustBankAccount</c> field BankGroupId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustBankAccountBankGroupId extends UPSPricingAttributeCustBankAccount implements UPSIPricingAttribute
{
}

