public str getName()
{
    return fieldPName(CustBankAccount, BankGroupId);
}

public Set getAllowedValues()
{
    var             ret = new Set(Types::String);
    CustBankAccount custBankAccount;

    while select custBankAccount
        group by BankGroupId
    {
        if (! ret.in(custBankAccount.BankGroupId))
        {
            ret.add(custBankAccount.BankGroupId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustBankAccount, BankGroupId));
    qbr.value(queryValue(_value));
}
